head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldinf26300";
scwin.diff = null;
scwin.dmenus = undefined;

///////// 2. 초기화 영역 /////////
// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — page

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "div_79", attr: "__html", fn: function () { return ([String(dma_page.get("total")), String(dma_page.get("currentPage")), String(dma_page.get("pageCount"))].some(function (v) { return String(v === null ? '' : v).trim() !== ''; }) ? ("총 <strong id=\"totPage\">" + String(dma_page.get("total")) + "</strong>건 <span id=\"totPage1\">(" + String(dma_page.get("currentPage")) + "/" + String(dma_page.get("pageCount")) + ")</span>") : ''); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        const v = a.fn();
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_page", fn: function(){ return (!(String(((dma_pageContext.get("page") ?? "")) === null ? '' : ((dma_pageContext.get("page") ?? ""))).length === 0)); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        const ok = !!b.fn();
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "cal_startDD", fn: function () { return String((dma_pageContext.get("startDD") ?? "")); } },
        { childId: "cal_endDD", fn: function () { return String((dma_pageContext.get("endDD") ?? "")); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_datefmt_cal_startDD
 * @description 초기화 — datefmt cal start DD
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_startDD = function () { $c.date.checkCalendarFormat("cal_startDD", "yyyyMMdd"); };

/**
 * @method
 * @name init_datefmt_cal_endDD
 * @description 초기화 — datefmt cal end DD
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_endDD = function () { $c.date.checkCalendarFormat("cal_endDD", "yyyyMMdd"); };

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        const pageIndex = "" + dma_page.get("currentPage") + "";
        const pageObj = $('.paging td:contains(' + pageIndex + ')');
        const pagingLeng = $('.paging td:contains(' + pageIndex + ')').length;
        for (let i = 0; i < pagingLeng; i++) {
            const obj = pageObj[i];
            const val = $(obj).text();
            if (pageIndex !== val) {
                continue;
            }
            const font = "<font color='blue'>" + val + "</font>";
            $(obj).html(font);
            $(obj).attr("style", "font-size:15px;");
        }
        $c.util.getComponent('ipt_dnldInstTpCd').setValue("12");
        let t1 = $c.util.getComponent('ipt_ck1').getValue(); if (t1 === null) { t1 = ''; }
        let t2 = $c.util.getComponent('ipt_ck2').getValue(); if (t2 === null) { t2 = ''; }
        let t3 = $c.util.getComponent('ipt_ck3').getValue(); if (t3 === null) { t3 = ''; }
        if ((t1 === "" && t2 === "" && t3 === "") || (t1 === "0")) {
            $("input[ipt_type=checkbox]").attr("checked", "checked");
        }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf26300.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.dmenus ={
        "bmenu":0,"mmenu":12
    }; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldinf26300' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        scwin.init_attrReals();
        scwin.init_conds();
        scwin.init_datefmt_cal_startDD();
        scwin.init_datefmt_cal_endDD();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldinf26300.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name ipt_ck1_onclick
 * @description 「0」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_ck1_onclick = function(e){
    try {
        scwin.SetChecked('__self.form')

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf26300.ipt_ck1_onclick' }); }
};

/**
 * @method
 * @name btn_appDate2_onclick
 * @description btn_appDate2 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_appDate2_onclick = function(e){
    try {
        scwin.appDate2('startDD','endDD',1)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf26300.btn_appDate2_onclick' }); }
};

/**
 * @method
 * @name btn_appDate2_2_onclick
 * @description btn_appDate2_2 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_appDate2_2_onclick = function(e){
    try {
        scwin.appDate2('startDD','endDD',3)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf26300.btn_appDate2_2_onclick' }); }
};

/**
 * @method
 * @name btn_appDate2_3_onclick
 * @description btn_appDate2_3 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_appDate2_3_onclick = function(e){
    try {
        scwin.appDate2('startDD','endDD',6)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf26300.btn_appDate2_3_onclick' }); }
};

/**
 * @method
 * @name btn_goSearch_onclick
 * @description btn_goSearch 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_goSearch_onclick = async function(e){
    try {
        await scwin.goSearch(1)

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf26300.btn_goSearch_onclick' }); }
};

/**
 * @method
 * @name btn_fnDownloadChk_onclick
 * @description btn_fnDownloadChk 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_fnDownloadChk_onclick = async function(e){
    try {
        await scwin.fnDownloadChk()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf26300.btn_fnDownloadChk_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_goSearch
 * @description go Search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_goSearch = async function () {
    try { return await $c.data.downFile("/down/downList.do?method=rmpDownList", "", ($c.util.getComponent("dma_goSearchReq") ? $c.util.getComponent("dma_goSearchReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name tx_fnExcelDown
 * @description fn Excel Down 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnExcelDown = async function () {
    try { return await $c.data.downFile("/down/excel.do?method=searchDownloadRmpExcel", "", ($c.util.getComponent("dma_fnExcelDownReq") ? $c.util.getComponent("dma_fnExcelDownReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name appDate2
 * @description 표준 API 조합으로 새로 작성한 검사 함수
 * @param {String} startId startId
 * @param {String} endId endId
 * @param {*} months months
 * @returns {void}
 * @hidden N
 */
scwin.appDate2 = function (startId, endId, months) { try { const end = $c.date.getServerDateTime(); const start = $c.date.addMonth(end, -Number(months || 0)); const r = function (nm) { return $c.util.getComponent('cal_' + nm) || $c.util.getComponent('ipt_' + nm) || $c.util.getComponent(String(nm)); }; const s = r(String(startId)); if (s && s.setValue) { s.setValue(start); } const e2 = r(String(endId)); if (e2 && e2.setValue) { e2.setValue(end); } } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'fn_appDate2' }); } };

/**
 * @method
 * @name open_corp_cd
 * @description open corp cd 처리
 * @returns {void}
 * @hidden N
 */
scwin.open_corp_cd = function () {
    formName = (document.JLDINF26300 || { elements: [] });
    fn_popupCorpSearch(formName);
};

/**
 * @method
 * @name toggleSearch
 * @description toggle Search 처리
 * @returns {void}
 * @hidden N
 */
scwin.toggleSearch = function () {
    const hiddenCheck = dma_hiddenStore.get("ipt_hiddenCheck");
    if (hiddenCheck === "N") {
        /* TODO Stage2: [sdd] 미실현 동작: set_visible (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_visible — {target}.setStyle({args}) */
        ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('ipt_hiddenCheck', "Y") : console.warn('[sdd] hiddenStore 부재: ipt_hiddenCheck'));
    } else {
        /* TODO Stage2: [sdd] 미실현 동작: set_visible (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_visible — {target}.setStyle({args}) */
        ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('ipt_hiddenCheck', "N") : console.warn('[sdd] hiddenStore 부재: ipt_hiddenCheck'));
    }
};

/**
 * @method
 * @name goSearch
 * @description go Search 처리
 * @param {Number} idx idx
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goSearch = async function (idx) {
    if ($c.util.getComponent('cal_startDD').getValue() > $c.util.getComponent('cal_endDD').getValue()) {
        await $c.win.alert("종료일은 시작일 이후 날짜로 입력하세요");
        $c.util.getComponent('dma_goSearchReq').set('endDate', "");
        return;
    }
    scwin.diff = $c.date.diffDate($c.util.getComponent('cal_startDD').getValue(), $c.util.getComponent('cal_endDD').getValue());
    if (scwin.diff > 365) {
        await $c.win.alert("조회 기간은 1년 이내로만 가능합니다.");
        $c.util.getComponent('dma_goSearchReq').set('endDate', "");
        return;
    }
    const checkWhere = "";
    let kind;
    const fm = (document.JLDINF26300 || { elements: [] });
    kind = "";
    if ((String($c.util.getComponent('ipt_ck2').getValue() || "") !== "")) {
        kind += $c.util.getComponent('ipt_ck2').getValue();
    }
    if ((String($c.util.getComponent('ipt_ck3').getValue() || "") !== "")) {
        kind += $c.util.getComponent('ipt_ck3').getValue();
    }
    $c.util.getComponent('dma_goSearchReq').set('checkWhere', kind);
    if (idx === '1') {
        $c.util.getComponent('ipt_pageIndex').setValue("1");
    }
    fm.action = "/down/downList.do?method=rmpDownList";
    fm.target = "_self";
    await scwin.tx_goSearch();
};

/**
 * @method
 * @name SetChecked
 * @description Set Checked 처리
 * @param {*} fm fm
 * @returns {void}
 * @hidden N
 */
scwin.SetChecked = function (fm) {
    if ((String($c.util.getComponent('ipt_ck1').getValue() || "") !== "")) {
        $c.util.getComponent("ipt_ck2").setValue(true);
        $c.util.getComponent("ipt_ck3").setValue(true);
    } else {
        $c.util.getComponent("ipt_ck2").setValue(false);
        $c.util.getComponent("ipt_ck3").setValue(false);
    }
};

/**
 * @method
 * @name fnDownloadChk
 * @description fn Download Chk 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnDownloadChk = async function () {
    const form = (document.JLDINF26300 || { elements: [] });
    fn_downInfoWin(form);
    await $c.win.alert("조회 내용이 없습니다.");
};

/**
 * @method
 * @name fnExcelDown
 * @description fn Excel Down 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnExcelDown = async function () {
    const checkWhere = "";
    let kind;
    const fm = (document.JLDINF26300 || { elements: [] });
    kind = "";
    if ((String($c.util.getComponent('ipt_ck2').getValue() || "") !== "")) {
        kind += $c.util.getComponent('ipt_ck2').getValue();
    }
    if ((String($c.util.getComponent('ipt_ck3').getValue() || "") !== "")) {
        kind += $c.util.getComponent('ipt_ck3').getValue();
    }
    $c.util.getComponent('dma_goSearchReq').set('checkWhere', kind);
    fm.action = '/down/excel.do?method=searchDownloadRmpExcel';
    fm.target = "iframeExcel";
    await scwin.tx_fnExcelDown();
};

/**
 * @method
 * @name krxpage_pagenavigator_88_onclick
 * @description krxpage_pagenavigator_88 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_88_onclick = async function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_goSearchReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_88.page' }); } await scwin.goSearch(index); };
